import assert from 'assert';
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { FrameResolver } from '../source/main/resolve';
import { generatedFrom, mapTsLineToCs, tokens } from '../source/shared/csharp';
import { decodeMappings, encodeVlq, originalPosition, parseSourceMap, sourceMappingUrl } from '../source/shared/sourcemap';
import { parseFrameLine } from '../source/shared/stack';
import { run, test } from './harness';

// ------------------------------------------------------------------ source maps

/** Builds "mappings" from [genLine][genCol, src, origLine, origCol] (absolute values). */
function encode(lines: number[][][]): string {
    let src = 0;
    let ol = 0;
    let oc = 0;
    return lines
        .map((segs) => {
            let gc = 0;
            return segs
                .map((s) => {
                    const out = encodeVlq(s[0] - gc) + encodeVlq(s[1] - src) + encodeVlq(s[2] - ol) + encodeVlq(s[3] - oc);
                    gc = s[0];
                    src = s[1];
                    ol = s[2];
                    oc = s[3];
                    return out;
                })
                .join(',');
        })
        .join(';');
}

test('VLQ round trip and decoding', () => {
    for (const v of [0, 1, -1, 15, 16, -16, 31, 32, 1000, -123456]) {
        const lines = decodeMappings(encodeVlq(0) + encodeVlq(0) + encodeVlq(v < 0 ? 0 : v) + encodeVlq(0));
        if (v >= 0) assert.strictEqual(lines[0][2], v);
    }
    assert.deepStrictEqual(decodeMappings('AAAA;;AACA'), [[0, 0, 0, 0], [], [0, 0, 1, 0]]);
    assert.deepStrictEqual(decodeMappings('A,AAAA'), [[0, 0, 0, 0]], 'one-field segments carry no source');
});

test('originalPosition picks the last segment at or before the column', () => {
    const mappings = encode([[[0, 0, 0, 0], [10, 0, 4, 2], [20, 1, 9, 0]], [], [[4, 0, 30, 6]]]);
    const map = parseSourceMap({ version: 3, sources: ['a.ts', 'b.ts'], mappings })!;
    assert.deepStrictEqual(originalPosition(map, 1, 1), { source: 'a.ts', line: 1, col: 1 });
    assert.deepStrictEqual(originalPosition(map, 1, 15), { source: 'a.ts', line: 5, col: 3 });
    assert.deepStrictEqual(originalPosition(map, 1, 25), { source: 'b.ts', line: 10, col: 1 });
    assert.strictEqual(originalPosition(map, 2, 1), null, 'unmapped line');
    assert.deepStrictEqual(originalPosition(map, 3, 0), { source: 'a.ts', line: 31, col: 7 }, 'col 0 takes the first mapping');
    assert.strictEqual(sourceMappingUrl('x();\n//# sourceMappingURL=abc.js.map\n'), 'abc.js.map');
});

// ------------------------------------------------------------------ C#

/** The extension folder (tests run from tests/out). */
const EXT = path.resolve(__dirname, /[\\/]out$/.test(__dirname) ? '../..' : '..');
const CS_DIR = path.join(EXT, '..', 'csharp', 'samples', 'assets', 'Scripts');

test('generatedFrom reads the csharp header', () => {
    assert.strictEqual(generatedFrom('// <auto-generated> from Rotator.cs by the C# extension. Edit the .cs file: this file is overwritten.'), 'Rotator.cs');
    assert.strictEqual(generatedFrom('﻿// <auto-generated> from My Thing.cs'), '', 'names with spaces are not generated by csharp');
    assert.strictEqual(generatedFrom('// <auto-generated> Cocos Creator API bindings'), '');
    assert.strictEqual(generatedFrom("import { _decorator } from 'cc';"), '');
});

test('tokens ignore keywords, this and leading underscores', () => {
    assert.deepStrictEqual(tokens('this._angle += this.speed * dt * dir;'), ['angle', 'speed', 'dt', 'dir']);
});

function lineOf(text: string, needle: string, from = 0): number {
    const lines = text.split(/\r?\n/);
    for (let i = from; i < lines.length; i++) if (lines[i].indexOf(needle) >= 0) return i + 1;
    throw new Error('not found: ' + needle);
}

test('mapTsLineToCs on the csharp samples (Rotator, PlayerController, ...)', () => {
    const ts = fs.readFileSync(path.join(CS_DIR, 'Rotator.ts'), 'utf8');
    const cs = fs.readFileSync(path.join(CS_DIR, 'Rotator.cs'), 'utf8');
    const cases: [string, string][] = [
        ["log('Rotator on ' + this.node.name);", 'log("Rotator on " + node.name);'],
        ['this._angle += this.speed * dt * dir;', '_angle += speed * dt * dir;'],
        ['this.turns++;', 'turns++;'],
        ['this.target.setRotationFromEuler(', 'target.setRotationFromEuler('],
        ['e.angle = this._angle;', 'e.angle = _angle;'],
        ['protected update(dt: number): void {', 'protected override void update(double dt)'],
    ];
    for (const [t, c] of cases) assert.strictEqual(mapTsLineToCs(ts, cs, lineOf(ts, t)), lineOf(cs, c), t);
    // every other sample: each statement line of a method maps inside the .cs file
    const names = fs.readdirSync(CS_DIR).filter((f) => f.endsWith('.ts'));
    assert.ok(names.length >= 5);
    for (const n of names) {
        const t2 = fs.readFileSync(path.join(CS_DIR, n), 'utf8');
        const csFile = path.join(CS_DIR, generatedFrom(t2.split(/\r?\n/)[0]));
        if (!fs.existsSync(csFile)) continue;
        const c2 = fs.readFileSync(csFile, 'utf8');
        const total = c2.split(/\r?\n/).length;
        t2.split(/\r?\n/).forEach((_l, i) => {
            const m = mapTsLineToCs(t2, c2, i + 1);
            assert.ok(m >= 1 && m <= total, n + ':' + (i + 1) + ' -> ' + m);
        });
    }
});

// ------------------------------------------------------------------ resolver on a fake project

function fakeProject(): string {
    const root = fs.mkdtempSync(path.join(os.tmpdir(), 'console-pro-'));
    const id = 'ab' + '0123456789abcdef0123456789abcdef012345';
    const chunkDir = path.join(root, 'temp', 'programming', 'packer-driver', 'targets', 'editor', 'chunks', 'ab');
    fs.mkdirSync(chunkDir, { recursive: true });
    fs.mkdirSync(path.join(root, 'assets', 'Scripts'), { recursive: true });
    const tsFile = path.join(root, 'assets', 'Scripts', 'Rotator.ts');
    fs.copyFileSync(path.join(CS_DIR, 'Rotator.ts'), tsFile);
    fs.copyFileSync(path.join(CS_DIR, 'Rotator.cs'), path.join(root, 'assets', 'Scripts', 'Rotator.cs'));
    const ts = fs.readFileSync(tsFile, 'utf8');
    const angleLine = lineOf(ts, 'this._angle += this.speed');
    // generated line 3, col 5 -> Rotator.ts angleLine, col 9
    const mappings = encode([[], [], [[4, 0, angleLine - 1, 8]]]);
    fs.writeFileSync(path.join(chunkDir, id + '.js'), 'System.register([], function () {\n  "use strict";\n    this._angle += 1;\n});\n//# sourceMappingURL=' + id + '.js.map');
    fs.writeFileSync(path.join(chunkDir, id + '.js.map'), JSON.stringify({ version: 3, sources: ['file:///' + tsFile.replace(/\\/g, '/')], mappings }));
    fs.mkdirSync(path.join(root, 'extensions', 'tool', 'dist'), { recursive: true });
    fs.writeFileSync(path.join(root, 'extensions', 'tool', 'dist', 'main.js'), 'x');
    return root;
}

test('FrameResolver: pack:/// chunk -> source map -> .ts -> .cs', async () => {
    const root = fakeProject();
    const r = new FrameResolver({ projectRoot: root, queryDbPath: async () => '', packagePath: (n) => (n === 'tool' ? path.join(root, 'extensions', 'tool') : '') });
    const ts = fs.readFileSync(path.join(root, 'assets', 'Scripts', 'Rotator.ts'), 'utf8');
    const cs = fs.readFileSync(path.join(root, 'assets', 'Scripts', 'Rotator.cs'), 'utf8');
    const f = parseFrameLine('    at Rotator.update (pack:///chunks/ab/ab0123456789abcdef0123456789abcdef012345.js:3:5)')!;
    const res = await r.resolve(f);
    assert.strictEqual(path.normalize(res.file), path.join(root, 'assets', 'Scripts', 'Rotator.ts'));
    assert.strictEqual(res.line, lineOf(ts, 'this._angle += this.speed'));
    assert.strictEqual(res.col, 9);
    assert.ok(res.mapped && res.user);
    assert.strictEqual(res.display, 'assets/Scripts/Rotator.ts:' + res.line + ':9');
    assert.ok(res.cs, 'the .cs file is offered');
    assert.strictEqual(res.cs!.line, lineOf(cs, '_angle += speed * dt * dir;'));

    // the same chunk as a file:// url of the editor target
    const f2 = parseFrameLine('    at x (file:///' + root.replace(/\\/g, '/') + '/temp/programming/packer-driver/targets/editor/chunks/ab/ab0123456789abcdef0123456789abcdef012345.js:3:5)')!;
    assert.strictEqual((await r.resolve(f2)).line, res.line);

    // db://assets and project-relative compiler paths
    const db = await r.resolve(parseFrameLine('    at y (db://assets/Scripts/Rotator.ts:4:1)')!);
    assert.strictEqual(db.line, 4);
    assert.ok(db.user && !db.mapped);
    const rel = await r.resolve({ fn: '', url: 'assets/Scripts/Rotator.cs', line: 12, col: 9, raw: '' });
    assert.ok(/Rotator\.cs$/.test(rel.file) && rel.line === 12);

    // packages:// urls and missing files
    const pkg = await r.resolve(parseFrameLine('    at z (packages://tool/dist/main.js:1:1)')!);
    assert.ok(/main\.js$/.test(pkg.file));
    const gone = await r.resolve(parseFrameLine('    at w (pack:///chunks/cd/cd0123456789abcdef0123456789abcdef012345.js:1:1)')!);
    assert.strictEqual(gone.file, '');
    assert.ok(!gone.user);
    fs.rmSync(root, { recursive: true, force: true });
});

test('FrameResolver on the real CocosGoat chunks (when temp/ exists)', async () => {
    const root = path.join(EXT, '..', '..');
    assert.ok(fs.existsSync(path.join(root, 'assets')), 'CocosGoat project root');
    const importMap = path.join(root, 'temp', 'programming', 'packer-driver', 'targets', 'editor', 'import-map.json');
    if (!fs.existsSync(importMap)) return;
    const imports: Record<string, string> = JSON.parse(fs.readFileSync(importMap, 'utf8')).imports;
    const key = Object.keys(imports).find((k) => /\/assets\/InputManagerSettings\.ts$/.test(k));
    if (!key) return;
    const rel = imports[key].replace(/^\.\//, '');
    const chunk = path.join(path.dirname(importMap), rel);
    const js = fs.readFileSync(chunk, 'utf8').split('\n');
    const gl = js.findIndex((l) => l.indexOf('.setAxes(AXES)') >= 0) + 1;
    assert.ok(gl > 0);
    const gc = js[gl - 1].indexOf('.setAxes') + 1;
    const r = new FrameResolver({ projectRoot: root, queryDbPath: async () => '', packagePath: () => '' });
    const res = await r.resolve({ fn: '', url: 'pack:///' + rel.replace(/\\/g, '/'), line: gl, col: gc, raw: '' });
    const src = fs.readFileSync(path.join(root, 'assets', 'InputManagerSettings.ts'), 'utf8');
    assert.ok(/InputManagerSettings\.ts$/.test(res.file), res.file);
    assert.strictEqual(res.line, lineOf(src, 'setAxes(AXES)'));
});

run();
